(* [comment removed for export] *)
Definition hz_F2_W (ff : Z) : list (Z * Z) := [(Z.shiftr ff 3 + 2147450880 + 34, Z.shiftr ff 3 + 2147450880 + 78)]%Z.
Scheme kc__1 := Elimination for Corelib.Init.Logic.and Sort Prop.

(* [comment removed for export] *)
Lemma hz_F2 : forall (LF : list fframe) (spa ff fp lo shi : Z)
    (sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s4 s5 s6 s7 s8 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem),
  0 <= spa -> spa + 64 <= 2^64 -> fresh_frame H LF 4 ff fp ->
  rw_cells bsegs m (Z.shiftr ff 3 + 2147450880) hz_sh3 ->
  mem_inv bsegs m -> as_RFS H ((4, ff, fp) :: LF) m -> ACONST m -> stack0 m lo shi ->
  evt bsegs (fun ms' => exists m',
      ms' = MS (mkR (Z_to_bv 64 P_HZ_RET_SDT) (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) (Z_to_bv 64 (spa + 32)) a1 a2 a3 a4 a5 a6 a7
                    (Z_to_bv 64 ff) (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) s4 s5 s6 s7 s8 (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) s11 t3 t4 t5 t6)
               F (Z_to_bv 64 P_A_STREAM_DTOR) fc None m' (seg_rom bsegs)
      /\ munch (hz_F2_W ff) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
      /\ rw_cells bsegs m' (Z.shiftr ff 3 + 2147450880) hz_sh2
      /\ as_RFS H ((4, ff, fp) :: LF) m' /\ ACONST m' /\ stack0 m' lo shi)
    (MS (mkR (Z_to_bv 64 P_HZ_RET_PDT) (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 ff) (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) s4 s5 s6 s7 s8 (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) s11 t3 t4 t5 t6)
